class Fighter:
    def __init__(self, health, attack_power):
        self.health = health
        self.attack_power = attack_power

    def take_damage(self, amount):
        self.health = max(0, self.health - amount)

    def is_destroyed(self):
        return self.health == 0

player = Fighter(30, 12)
foes = [Fighter(10, 5), Fighter(10, 5)]

while not player.is_destroyed() and foes:
    target = foes[0]
    target.take_damage(player.attack_power)
    if target.is_destroyed():
        foes.pop(0)
        print(f"A foe fell! {len(foes)} left.")
    if foes:
        player.take_damage(foes[0].attack_power)

print("Player HP:", player.health)

