class Ship:
    def __init__(self, health, attack_power):
        self.health = health
        self.attack_power = attack_power

    def take_damage(self, amount):
        self.health = max(0, self.health - amount)

    def is_destroyed(self):
        return self.health == 0


class Alien:
    def __init__(self, health, attack_power):
        self.health = health
        self.attack_power = attack_power

    def take_damage(self, amount):
        self.health = max(0, self.health - amount)

    def is_destroyed(self):
        return self.health == 0


def run_battle(ship, fleet):
    while not ship.is_destroyed() and fleet:
        target = fleet[0]
        target.take_damage(ship.attack_power)
        if target.is_destroyed():
            fleet.pop(0)
            print(f"An alien was destroyed! {len(fleet)} remaining.")
        else:
            print(f"Alien HP: {target.health}")
        if fleet:
            attacker = fleet[0]
            ship.take_damage(attacker.attack_power)
            print(f"Ship HP: {ship.health}")

    if fleet:
        print("Defeat! The ship was destroyed.")
    else:
        print("Victory! The fleet was destroyed.")
